/**
 * Tabs.Content: one tab’s panel.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tabs.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { useContext, type JSX } from 'solid-js'

import { claimSlot, mergeParts, ownerContext, scope } from '@polymorph/solid'
import styles from '@polymorph/recipes/overlays/tabs.module.css'
import type { TabsOwner } from './Tabs'

export interface TabsContentProps {
  children: JSX.Element
  /**
   * The value of the tab this panel belongs to.
   */
  value: string
}

/** Tabs.Content: one tab’s panel. */
export default function TabsContent(given: TabsContentProps): JSX.Element {
  const props = claimSlot(given)
  const owner = useContext(ownerContext<TabsOwner>('Tabs')) ?? ({} as TabsOwner)
  return scope(() => {
    return (
      <>
        {owner.keepMounted || owner.api?.value === props.value ? (
          <div
            {...mergeParts(owner.api?.getContentProps({ value: props.value }) ?? {}, {
              class: styles.content,
              'data-tabs-part': 'tabpanel',
              'data-state': owner.api?.value === props.value ? 'active' : 'inactive',
            })}
          >
            {props.children}
          </div>
        ) : null}
      </>
    )
  })
}
